  "version": "1.0.0",
  "private": true,
  "description": "A real-time message board using PGLite and Server-Sent Events",
  "scripts": {
    "dev:server": "node server/index.js",
    "dev:client": "cd client && npx vite --host",
    "dev": "npm-run-all --parallel dev:server dev:client",
